import pytest

from kvcache import LRUCache


def test_get_missing_returns_default():
    assert LRUCache().get("x", 5) == 5


def test_eviction_order():
    c = LRUCache(2)
    c.set("a", 1)
    c.set("b", 2)
    c.get("a")
    c.set("c", 3)
    assert "b" not in c and "a" in c and "c" in c


def test_len_tracks_capacity():
    c = LRUCache(3)
    for i in range(10):
        c.set(i, i)
    assert len(c) == 3


def test_invalid_capacity():
    with pytest.raises(ValueError):
        LRUCache(0)
from conftest import requires_redis


@requires_redis
def test_get_or_compute_caches_value(cache):
    calls = []

    def compute():
        calls.append(1)
        return {"n": 42}

    assert cache.get_or_compute("a", compute) == {"n": 42}
    assert cache.get_or_compute("a", compute) == {"n": 42}
    assert len(calls) == 1


@requires_redis
def test_get_or_compute_caches_falsy_value(cache):
    calls = []

    def compute():
        calls.append(1)
        return 0

    assert cache.get_or_compute("zero", compute) == 0
    assert cache.get_or_compute("zero", compute) == 0
    assert len(calls) == 1
from kvcache import serializers


def test_roundtrip():
    assert serializers.loads(serializers.dumps({"b": [1, 2], "a": None})) == {"b": [1, 2], "a": None}


def test_loads_bytes():
    assert serializers.loads(b"[1, 2]") == [1, 2]


def test_loads_none():
    assert serializers.loads(None) is None

